class Solution { bool between(int value,int left,int right){return min(left,right)<value&&value<max(left,right);}public:int minMovesToCaptureTheQueen(int a,int b,int c,int d,int e,int f){if(a==e&&!(c==a&&between(d,b,f)))return 1;if(b==f&&!(d==b&&between(c,a,e)))return 1;if(abs(c-e)==abs(d-f)){bool blocked=abs(a-c)==abs(b-d)&&between(a,c,e)&&between(b,d,f);if(!blocked)return 1;}return 2;} };
